import html, re, sqlite3
from pathlib import Path
p=Path('tmp/rmlau-samarth.FRUYgm/https___rmlauadm_samarth_edu_in_index_php_site_programme.html')
text=p.read_text()
pat=re.compile(r'<span class=\"duration-badge\">\\s*(["'^<]+?)'"\\s*</span>.*?<h6["'^>]*>(.*?)</h6>.*?<small class="text-muted">Eligibility</small>'"\\s*<p>(.*?)</p>',re.S)
def clean(v):
 v=re.sub(r'<["'^>]+>'"','',v); v=html.unescape(v).replace('\\xa0',' '); return re.sub(r'\\s+',' ',v).strip().rstrip('\"').strip()
rows=[(clean(a),clean(b),clean(c) or None) for a,b,c in pat.findall(text)]
ids=[348,337,347,46,42,67,269,93,None,None,72,69,57,59,78,35,26,79,79,68,14,153,70,90,32,146,66,None,73,84,83,89,80,85,82,78,78,339,273,281,82,83,73,57,267,73,60,None,59,143,143,198,83,80,89,85,82,20,31,84,80,82,85,89,83,21,155,81,3,None,69,30,30,68,89,82,247,30,73,30,70,90,198,30,30,30,None,90,70,348,153,21,155,281,30,75,281,66,73,73,None,29,None,None,None,None,21,84,75,80,83,80,89,281,321,26,321,26,93,69,46,21,143,None,34,347,30,201,20,347]
assert len(rows)==len(ids)==130
con=sqlite3.connect('file:assets/data/career_path.db?mode=ro',uri=True)
con.row_factory=sqlite3.Row
nodes={r['id']:dict(r) for r in con.execute('select id,slug,stream_id,parent_id,name from career_nodes')}
streams={r['id']:r['name'] for r in con.execute('select id,name from streams')}
def crumb(i):
 parts=[]; cur=i
 while cur:
  n=nodes[cur]; parts.append(n['name']); cur=n['parent_id']
 parts.append(streams[nodes[i]['stream_id']]); return ' > '.join(reversed(parts))
for i,(row,nid) in enumerate(zip(rows,ids),1):
 if 'Test Programme' in row[1]: continue
 if nid is None: print(f'{i:3} GAP {row[1]}')
 else: print(f'{i:3} {nid:3} {nodes[nid][\"slug\"]}\\t{crumb(nid)}')
print('active',sum('Test Programme' not in r[1] for r in rows),'gaps',sum(nid is None and 'Test Programme' not in r[1] for r,nid in zip(rows,ids)))
